const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const auth=input.authorization??{};
const pkg=input.closing_package??{};
const blockers=arr(input.blockers);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const finalReady=truthy(input.final_closing_ready)||["final_closing_ready","ready","authorized"].includes(String(input.status||"").toLowerCase());
const packageFinalized=truthy(pkg.finalized)||["finalized","ready","complete"].includes(String(pkg.status||"").toLowerCase());
const authorizationConfirmed=truthy(auth.confirmed)||["confirmed","authorized","approved"].includes(String(auth.status||"").toLowerCase());
const authorizationType=String(auth.type||auth.authorization_type||"").trim();
const authorizedBy=String(auth.authorized_by||auth.approved_by||"").trim();
const launchKey=String(input.launch_idempotency_key||input.execution_idempotency_key||"").trim();
const launchEvidence=input.launch_evidence??{};
const alreadyLaunched=truthy(input.execution_launched)||truthy(launchEvidence.confirmed)||["launched","active","confirmed"].includes(String(launchEvidence.status||"").toLowerCase());
const duplicateSafe=Boolean(launchKey)&&(!alreadyLaunched||Boolean(launchEvidence.idempotency_key===launchKey));
const blockersClear=blockers.length===0;
const closingDateValid=Boolean(input.closing_date)&&!Number.isNaN(new Date(input.closing_date).getTime());

let status="authorization_required",nextWorkflow="WF-278",humanReview=true;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";}
else if(!packageFinalized||!finalReady){status="final_readiness_not_confirmed";nextWorkflow="WF-277";}
else if(!blockersClear||!closingDateValid){status="blocked";nextWorkflow="WF-126";}
else if(!authorizationConfirmed||!authorizationType||!authorizedBy){status="explicit_authorization_required";nextWorkflow="WF-278";}
else if(!launchKey){status="launch_idempotency_key_required";nextWorkflow="WF-278";}
else if(alreadyLaunched&&duplicateSafe){status="already_launched";nextWorkflow="WF-279";}
else if(!duplicateSafe){status="launch_conflict";nextWorkflow="WF-126";}
else{status="closing_execution_launch_ready";nextWorkflow="WF-279";}

return [{json:{...input,workflow:"WF-278",workflow_name:"Final Closing Authorization → Closing Execution Launch Controller",status,launch_authorization:{identity_complete:identityComplete,final_readiness_confirmed:finalReady,package_finalized:packageFinalized,blockers_clear:blockersClear,closing_date_valid:closingDateValid,authorization_confirmed:authorizationConfirmed,authorization_type_present:Boolean(authorizationType),authorized_by_present:Boolean(authorizedBy),launch_idempotency_key_present:Boolean(launchKey),already_launched:alreadyLaunched,duplicate_safe:duplicateSafe,ready:["closing_execution_launch_ready","already_launched"].includes(status)},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"final_closing_authorization_execution_launch",idempotency_key:input.idempotency_key||`wf-278:${input.deal_id||"unknown"}:${launchKey||"none"}:${input.version||1}`}}}];
